(function(){
  const S = NOVA_SEMILLA;
  const yaCargada = d => !!(d && d.config && d.config.semilla === S.version);
  const conSemilla = d => {
    d = d || {};
    d.config = Object.assign({horasEdicion:48, toleranciaVariacion:5}, d.config || {}, {semilla:S.version});
    d.programaciones = JSON.parse(JSON.stringify(S.programaciones));
    d.historial = JSON.parse(JSON.stringify(S.historial));
    return d;
  };
  const subir = () => { if (window.NOVA_NUBE) window.NOVA_NUBE.subir(datosCompartidos()); };
  let aplicarBase = null, aplicar = null, vacia = null;
  Object.defineProperty(window, 'novaAplicarRemoto', { configurable: true,
    get(){ return aplicar; },
    set(fn){ aplicarBase = fn; aplicar = d => { if (yaCargada(d)) return fn(d); fn(conSemilla(d)); subir(); }; }
  });
  Object.defineProperty(window, 'novaNubeVacia', { configurable: true,
    get(){ return vacia; },
    set(fn){ vacia = () => { const d = datosCompartidos(); if (yaCargada(d)) return fn(); aplicarBase(conSemilla(d)); subir(); }; }
  });
  // Sin conexión a la nube (por ejemplo, al abrir index.html con doble clic): carga las semanas en este equipo.
  window.addEventListener('load', () => setTimeout(() => {
    if (window.NOVA_NUBE || !aplicarBase) return;
    const d = datosCompartidos();
    if (!yaCargada(d)) aplicarBase(conSemilla(d));
  }, 1500));
})();
